class Solution {
    public int removeElement(int[] nums, int val) {
        int length = nums.length;
        int index = 0;
        while (index < length) {
            if (nums[index] == val) {
                for (int shift = index; shift < length - 1; shift++) {
                    nums[shift] = nums[shift + 1];
                }
                length--;
            } else {
                index++;
            }
        }
        return length;
    }
}

